<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/bootstrap.php';
$page=$_GET['page'] ?? (current_user()?'dashboard':'login');
$public=['login']; $admin=['admin']; $staff=['admin','librarian'];
try {
 if(is_post()) {
  verify_csrf(); $action=$_POST['action']??'';
  if($action==='login') { if(Auth::attempt(trim($_POST['username']??''),$_POST['password']??'')) redirect('dashboard'); flash('danger','Invalid username or password, or account inactive.'); redirect('login'); }
  require_login();
  if($action==='logout') { Auth::logout(); header('Location: index.php?page=login'); exit; }
  if($action==='book_save') { require_role($staff); $id=(int)($_POST['book_id']??0); $data=[(int)$_POST['category_id'],trim($_POST['isbn']),trim($_POST['title']),trim($_POST['author']),trim($_POST['publisher']),max(0,(int)$_POST['total_copies']),max(0,(int)$_POST['total_copies'])]; if($id){$q=db()->prepare('UPDATE books SET category_id=?,isbn=?,title=?,author=?,publisher=?,total_copies=?,available_copies=LEAST(available_copies,?) WHERE book_id=?');$q->execute([...$data,$id]);}else{$q=db()->prepare('INSERT INTO books(category_id,isbn,title,author,publisher,total_copies,available_copies) VALUES(?,?,?,?,?,?,?)');$q->execute($data);} flash('success','Book saved successfully.'); redirect('books'); }
  if($action==='book_update') { require_role($staff); $id=(int)$_POST['book_id']; $total=max(0,(int)$_POST['total_copies']); $q=db()->prepare("SELECT COUNT(*) FROM book_transactions WHERE book_id=? AND status='issued'"); $q->execute([$id]); $borrowed=(int)$q->fetchColumn(); if($total<$borrowed) throw new RuntimeException('Total copies cannot be lower than the number currently on loan.'); $q=db()->prepare('UPDATE books SET category_id=?,isbn=?,title=?,author=?,publisher=?,total_copies=?,available_copies=? WHERE book_id=?'); $q->execute([(int)$_POST['category_id'],trim($_POST['isbn']),trim($_POST['title']),trim($_POST['author']),trim($_POST['publisher']),$total,$total-$borrowed,$id]); flash('success','Book details updated.'); redirect('books'); }
  if($action==='book_delete') { require_role($admin); $q=db()->prepare("SELECT COUNT(*) FROM book_transactions WHERE book_id=? AND status='issued'");$q->execute([(int)$_POST['book_id']]); if((int)$q->fetchColumn()>0) throw new RuntimeException('Cannot delete a book with active loans.'); db()->prepare("UPDATE books SET status='archived' WHERE book_id=?")->execute([(int)$_POST['book_id']]); flash('success','Book archived.'); redirect('books'); }
  if($action==='category_save') { require_role($staff); db()->prepare('INSERT INTO categories(category_name,description) VALUES(?,?) ON DUPLICATE KEY UPDATE description=VALUES(description)')->execute([trim($_POST['category_name']),trim($_POST['description'])]); flash('success','Category saved.'); redirect('categories'); }
  if($action==='user_save') { require_role($admin); $role=$_POST['role']; if(!in_array($role,['student','librarian','admin'],true)) throw new RuntimeException('Invalid role.'); $username=trim($_POST['username']); $email=trim($_POST['email']); $name=trim($_POST['full_name']); $password=$_POST['password']; if(strlen($password)<10) throw new RuntimeException('Password must contain at least 10 characters.'); $pdo=db();$pdo->beginTransaction(); try{$q=$pdo->prepare('INSERT INTO users(username,email,password_hash,role,full_name) VALUES(?,?,?,?,?)');$q->execute([$username,$email,password_hash($password,PASSWORD_DEFAULT),$role,$name]);$uid=(int)$pdo->lastInsertId(); if($role==='student')$pdo->prepare('INSERT INTO students(user_id,student_number,department) VALUES(?,?,?)')->execute([$uid,trim($_POST['identity_number']),trim($_POST['department'])]); if($role==='librarian')$pdo->prepare('INSERT INTO librarians(user_id,employee_number) VALUES(?,?)')->execute([$uid,trim($_POST['identity_number'])]);$pdo->commit();}catch(Throwable $e){$pdo->rollBack();throw $e;} flash('success','User account created.'); redirect('users'); }
  if($action==='issue') { require_role($staff); $q=db()->prepare('SELECT student_id FROM students WHERE user_id=?'); $q->execute([(int)$_POST['user_id']]); $sid=(int)$q->fetchColumn(); if(!$sid) throw new RuntimeException('Student record not found.'); LibraryService::issue((int)$_POST['book_id'],$sid,(int)current_user()['user_id']); flash('success','Book issued.'); redirect('loans'); }
  if($action==='return') { require_role($staff); $fine=LibraryService::returnBook((int)$_POST['transaction_id'],(int)current_user()['user_id']); flash('success','Book returned. Fine: '.money($fine)); redirect('loans'); }
  if($action==='fine_paid') { require_role($staff); db()->prepare("UPDATE fines SET payment_status='paid',paid_at=NOW() WHERE fine_id=?")->execute([(int)$_POST['fine_id']]); flash('success','Fine marked as paid.'); redirect('fines'); }
  if($action==='settings_save') { require_role($admin); foreach(['max_books_per_student','loan_period_days','daily_fine_rate'] as $key){$value=trim((string)($_POST[$key]??'')); if(!is_numeric($value)||($key!=='daily_fine_rate'&&(int)$value<1)||(float)$value<0) throw new RuntimeException('Invalid policy value.'); db()->prepare('INSERT INTO system_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$key,$value]);} flash('success','Library policies updated.'); redirect('settings'); }
 }
 if(!in_array($page,$public,true)) require_login();
 $user=current_user();
 if($user && $page==='login') redirect('dashboard');
 $role=$user['role']??'';
 $title=ucfirst(str_replace('_',' ',$page));
 include dirname(__DIR__).'/views/layout.php';
} catch(Throwable $e) { if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack(); error_log((string)$e); flash('danger', (getenv('APP_DEBUG')==='true'?$e->getMessage():'The request could not be completed. Check the application log.')); redirect($page==='login'?'login':'dashboard'); }
